"""I <3 PY -- the parametric heart, standalone.

The exact curve drawn at github.com/otrobonita-studios/i-love-python,
lifted out to one runnable file. No app, no browser -- just the math:

    x(t) = 16 * sin(t)**3
    y(t) = 13*cos(t) - 5*cos(2t) - 2*cos(3t) - cos(4t)

Drag t to walk the point around the outline; drag samples to change how
finely the curve is traced (heart_xy needs at least 3 points).

Needs:  pip install numpy matplotlib
Run:    python heart_curve.py
"""

from __future__ import annotations

import math

import matplotlib.pyplot as plt
import numpy as np
from matplotlib.widgets import Slider

HEART_RED = "#EE1C25"


def heart_xy(t: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """The parametric heart, vectorized over an array of t (radians)."""
    x = 16.0 * np.sin(t) ** 3
    y = 13.0 * np.cos(t) - 5.0 * np.cos(2 * t) - 2.0 * np.cos(3 * t) - np.cos(4 * t)
    return x, y


def main() -> None:
    fig, ax = plt.subplots(figsize=(6, 6.6), facecolor="black")
    fig.subplots_adjust(bottom=0.22)
    ax.set_facecolor("black")
    ax.set_aspect("equal")
    ax.axis("off")
    ax.set_xlim(-19, 19)
    ax.set_ylim(-19, 8)

    (curve_line,) = ax.plot([], [], color=HEART_RED, lw=2)
    (point_dot,) = ax.plot([], [], "o", color=HEART_RED, markersize=9)
    readout = ax.text(
        0,
        1,
        "",
        ha="center",
        va="center",
        color=HEART_RED,
        family="monospace",
        fontsize=11,
        fontweight="bold",
    )

    ax_t = fig.add_axes((0.18, 0.11, 0.64, 0.035))
    ax_n = fig.add_axes((0.18, 0.05, 0.64, 0.035))
    for slider_ax in (ax_t, ax_n):
        slider_ax.set_facecolor("#222222")
    slider_t = Slider(ax_t, "t", 0.0, 2 * math.pi, valinit=0.0, color=HEART_RED)
    slider_n = Slider(ax_n, "samples", 8, 240, valinit=240, valstep=1, color=HEART_RED)
    for slider in (slider_t, slider_n):
        slider.label.set_color("white")
        slider.valtext.set_color("white")

    def redraw(_value: float | None = None) -> None:
        n = int(slider_n.val)
        t_curve = np.linspace(0, 2 * math.pi, n, endpoint=False)
        xs, ys = heart_xy(t_curve)
        curve_line.set_data(xs, ys)

        t = slider_t.val
        px, py = heart_xy(np.array([t]))
        point_dot.set_data(px, py)
        readout.set_text(
            f"t = {t:.2f}\n"
            f"x = 16·sin³(t) = {px[0]:.1f}\n"
            f"y = {py[0]:.1f}"
        )
        fig.canvas.draw_idle()

    slider_t.on_changed(redraw)
    slider_n.on_changed(redraw)
    redraw()
    plt.show()


if __name__ == "__main__":
    main()
